import{z as l,x as s,o as A,c as p,q as B,j as n,D as r,d as e,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"研发竞赛与专利","description":"","frontmatter":{"title":"研发竞赛与专利","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rnd-patent-races.md","filePath":"econ/rnd-patent-races.md","lastUpdated":1791063341000}'),d={name:"econ/rnd-patent-races.md"};function m(h,E,u,D,C,c){const t=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=B('<h1 id="研发竞赛与专利" tabindex="-1">研发竞赛与专利 <a class="header-anchor" href="#研发竞赛与专利" aria-label="Permalink to &quot;研发竞赛与专利&quot;">​</a></h1><div class="epigraph"><p>专利用一段暂时的排他权买持续的发明；竞赛里烧掉的是所有参赛者的投入，留下的只有一个赢家和一纸排他。</p><footer>—— 据 Dasgupta and Stiglitz, Bell Journal 1980；Gilbert and Shapiro, AER 1990 整理</footer></div><p><a href="/econ/predation-exclusion">上一课</a>把产业组织主干收束在「谁在场」上：完全资本市场、单市场下补偿往往不可信，摩擦把它打开；合并改所有权，掠夺与排他改谁在场，反事实更长。本课起是加深层「创新与纵向」的第一课，不换课程，只把主干的两条静维打开：产品会换代，于是有竞赛与奖品设计——本课；供给有上下游，边界与控制权留给本单元后三课。增长主干已把创造性破坏收进总量的 \\(g\\)（<a href="/econ/ak-variety-schumpeter">AK、种类与熊彼特</a>，引擎是 Aghion–Howitt 1992）；本课给竞赛季度的产业组织：谁投入、何时抢跑、奖品多宽。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞赛的结构：\\(n\\) 家投入 \\(x_i\\)，创新按泊松到达率 \\(\\lambda(x_i)\\) 随机降临，先到者拿专利。投入全部沉没，赢家只有一个——这正是<a href="/econ/all-pay-auction">全支付拍卖</a>在时间维的版本，烧钱注定收不回。缺口不是把拍卖再讲一遍，而是两个制度问题的叠加：竞赛的投入总量是否恰当（耗散问题）；专利作为奖品怎么定价（长度与宽度）。Arrow 1962 的替代效应补一刀：在位者创新只是自己换自己，激励天然弱于挑战者。</p><p>个体的一阶条件：边际投入提高自身到达率 \\(\\lambda_i&#39;(x_i)\\)，乘上赢的概率与奖品现值 \\(v\\)，等于边际成本。把 \\(n\\) 家加总与社会的比较，两股力反向：商业窃取效应——每家只算自己赢，不算挤掉对手本可共享的租，推<strong>过度</strong>投入；溢出效应——没有排他时知识外漏，后来者白捡，推<strong>投入不足</strong>。净号不定，是竞赛文献的总判断。</p>',6)),(A(),n(o,null,{default:r(()=>[i(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20XI%5B%22%E5%90%84%E5%AE%B6%E6%8A%95%E5%85%A5%20x_i%22%5D%20--%3E%20LAM%5B%22%E5%88%B0%E8%BE%BE%E7%8E%87%20%CE%BB(x_i)%22%5D%0A%20%20LAM%20--%3E%20RACE%5B%22%E5%85%88%E5%88%B0%E8%80%85%E6%8B%BF%E4%B8%93%E5%88%A9%22%5D%0A%20%20PAT%5B%22%E5%A5%96%E5%93%81%E8%AE%BE%E8%AE%A1%EF%BC%9A%E9%95%BF%E5%BA%A6%20T%20%C3%97%20%E5%AE%BD%E5%BA%A6%20b%22%5D%20--%3E%20V%5B%22%E5%A5%96%E5%93%81%E7%8E%B0%E5%80%BC%20v%22%5D%0A%20%20V%20--%3E%20XI%0A%20%20SPILL%5B%22%E6%BA%A2%E5%87%BA%EF%BC%9A%E7%9F%A5%E8%AF%86%E5%A4%96%E6%BC%8F%22%5D%20--%3E%20SOC%5B%22%E7%A4%BE%E4%BC%9A%E8%AF%84%E4%BC%B0%EF%BC%9A%E8%80%97%E6%95%A3%E5%AF%B9%E6%BF%80%E5%8A%B1%22%5D%0A%20%20RACE%20--%3E%20SOC%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"耗散的量级：奖品 \\(v\\) 给定、到达率对投入足够敏感时，对称均衡的总投入可以逼近 \\(v\\) 本身——预期的垄断租几乎全部烧进竞赛。缓解它的是到达率的凸性递减与边际成本上升，不是制度的善意。")],-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"商业窃取效应翻译成大白话：我赢，等于把对手（或消费者）本可共享的利润抢进自家碗——私人账上算收益，社会账上只是搬钱，于是容易投过头。溢出效应相反：知识会漏给后来者，自己留不住全部回报，于是容易投不够。两股力方向相反，净号不定。")],-1)),E[5]||(E[5]=a("h2",{id:"方法",tabindex:"-1"},[e("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[6]||(E[6]=a("p",null,[e("奖品设计写成两个旋钮。长度 \\(T\\)：专利期的垄断租流量，Nordhaus 1969 的经典权衡——越长激励越足，静态垄断损失越久。宽度 \\(b\\)：后来的改进产品离多远才算侵权。Gilbert–Shapiro 1990 论证两者可以互换：窄而长的专利近似于按使用收费的激励，静态损失小；Klemperer 1990 补充：宽度管的是"),a("strong",null,"后续创新者的自由"),e("，产品替代性越强的市场，宽度的代价越高。于是专利制度不是「保护或不保护」的开关，而是 \\((T,b)\\) 平面上的一个点，替代品结构与技术阶梯的形状决定哪个点最不坏。")],-1)),(A(),n(o,null,{default:r(()=>[i(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%A5%96%E5%93%81%E8%AE%BE%E8%AE%A1%EF%BC%9AT%20%E4%B8%8E%20b%20%E4%B8%A4%E4%B8%AA%E6%97%8B%E9%92%AE%22%5D%20--%3E%20T%5B%22%E9%95%BF%E5%BA%A6%20T%EF%BC%9A%E5%9E%84%E6%96%AD%E6%9C%9F%E5%A4%9A%E4%B9%85%22%5D%0A%20%20P%20--%3E%20B%5B%22%E5%AE%BD%E5%BA%A6%20b%EF%BC%9A%E5%A4%9A%E8%BF%9C%E7%AE%97%E4%BE%B5%E6%9D%83%22%5D%0A%20%20T%20--%3E%20TC%5B%22%E8%B6%8A%E9%95%BF%E6%BF%80%E5%8A%B1%E8%B6%8A%E8%B6%B3%EF%BC%8C%E9%9D%99%E6%80%81%E6%8D%9F%E5%A4%B1%E8%B6%8A%E4%B9%85%22%5D%0A%20%20B%20--%3E%20BC%5B%22%E8%B6%8A%E5%AE%BD%E5%90%8E%E7%BB%AD%E5%88%9B%E6%96%B0%E8%87%AA%E7%94%B1%E8%B6%8A%E5%B0%8F%22%5D%0A%20%20GS%5B%22Gilbert%E2%80%93Shapiro%EF%BC%9A%E7%AA%84%E8%80%8C%E9%95%BF%E5%8F%AF%E8%BF%91%E4%BC%BC%E6%8C%89%E4%BD%BF%E7%94%A8%E6%94%B6%E8%B4%B9%22%5D%20--%3E%20SWAP%5B%22%E4%B8%A4%E6%97%8B%E9%92%AE%E9%83%A8%E5%88%86%E4%BA%92%E6%8D%A2%22%5D%0A%20%20SWAP%20--%3E%20POINT%5B%22%E5%88%B6%E5%BA%A6%E6%98%AF%E5%9C%A8%20(T%2Cb)%20%E5%B9%B3%E9%9D%A2%E4%B8%8A%E9%80%89%E6%9C%80%E4%B8%8D%E5%9D%8F%E7%9A%84%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=B('<p>抢跑是竞赛的动态层。Reinganum 1981 的先行采用与扩散：在位者与新进入者谁先换代，取决于租的算术——在位者换代会自我蚕食（Arrow 效应），于是往往<strong>等</strong>；Fudenberg–Gilbert–Stiglitz–Tirole 1983 把抢跑与跳蛙写成正式博弈：领先者稍有松懈，挑战者就加足投入反超。沉睡专利是抢跑的静态残迹，未必是低效，也可能是竞赛均衡的一部分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么用竞赛而不是补贴：信息不对称。全社会不知道哪个技术方向值得多少，竞赛让厂商用自己的钱投票， DARPA 与奖励奖金是另两种奖品形态，专利的相对优势是把定价权交给事后的市场销售额。耗散不一定是坏事：烧掉的租若不设竞赛，也会以垄断定价从消费者手里收走——两种去向，看生产率收益落在哪边。</p><p><span class="marginnote">直觉类比：抢一个 100 万元的奖品，若多烧 1 万元投入就能明显提高胜率，人人都会加码，最后各家合计可能烧掉近 100 万元——奖品没变，社会只多出一堆沉没的实验室。这就是「耗散」：预期的租被竞争本身烧掉。</span></p><p>与增长主干的分工再钉一次：<a href="/econ/ak-variety-schumpeter">AK、种类与熊彼特</a>把创新率收进 \\(\\dot A/A\\) 的总量参数；本课把同一件事拆到季度——进入决策、投入强度、抢跑时序。错在哪：把专利制度的福利写成「垄断坏，所以越短越好」，没有奖品就没有竞赛；或反过来「激励越强越好」，无视全支付耗散与对后续创新的封锁。政策辩论里两个方向的口号都很响，机制上它们是同一个权衡的两端。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估专利制度改革的实证弹性，不写侵权诉讼与标准必要专利的法律要件。长度与宽度的互换在替代结构复杂的行业失灵：宽度太细，诉讼成本本身就是耗散。竞赛模型假设到达率只随投入动；组合式创新的「堵路」（反公地）问题超出本课的单奖品框架。创新补贴与研发税式支出的接力留给树序。</p><p><span class="marginnote">常见误区：专利不是「保护越强越好」的盾牌。长度与宽度都在从别人那里拿东西：长度拿的是消费者的静态剩余，宽度拿的是后续创新者的自由，两者都有成本。说「垄断坏所以越短越好」和「激励强所以越长越好」，是同一个权衡的两端口号。</span></p><p>后课默认：产品的时间维已经打开，下一课处理需求侧的人造变量——广告——为什么它不是营销学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>专利竞赛是时间维的全支付拍卖：投入沉没，赢家通吃。</li><li>商业窃取推过度投入，溢出推投入不足，净号不定。</li><li>奖品设计是长度与宽度的二维权衡（Nordhaus；Gilbert–Shapiro；Klemperer）。</li><li>抢跑、跳蛙与在位者的自我蚕食（Arrow 效应）定竞赛的时序。</li><li>出处：Dasgupta–Stiglitz 1980；Reinganum 1981；Aghion–Howitt 1992；Gilbert–Shapiro 1990。</li></ul>',11))])}const g=l(d,[["render",m]]);export{b as __pageData,g as default};
